<section class="panel"><div class="panel-header"><div><h2>Catálogo de jogos</h2><p><?= count($games) ?> registro(s) encontrado(s).</p></div><a class="btn btn-primary" href="index.php?entidade=games&acao=novo">+ Novo jogo</a></div>
<form class="filters" method="get"><input type="hidden" name="entidade" value="games"><div class="field grow"><label for="buscar">Pesquisar</label><input id="buscar" type="search" name="buscar" value="<?= e($busca) ?>" placeholder="Título ou descrição"></div><button class="btn btn-secondary" type="submit">Buscar</button></form>
<?php if (!$games): ?><div class="empty-state">Nenhum jogo encontrado.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Imagem</th><th>Jogo</th><th>Categoria</th><th>Preço</th><th>Estoque</th><th>Ações</th></tr></thead><tbody>
<?php foreach ($games as $game): ?><tr><td><?php if (!empty($game['imagem'])): ?><img src="../../public/imagens/<?= e(basename($game['imagem'])) ?>" alt="Capa de <?= e($game['titulo']) ?>" style="width:54px;height:64px;object-fit:cover;border-radius:8px"><?php else: ?>—<?php endif; ?></td><td class="text-left"><strong><?= e($game['titulo']) ?></strong><br><small class="muted"><?= e((function_exists('mb_strimwidth') ? mb_strimwidth($game['descricao'],0,90,'…','UTF-8') : substr($game['descricao'],0,90))) ?></small></td><td><?= e($game['categoria_nome']) ?></td><td>R$ <?= number_format((float)$game['preco'],2,',','.') ?></td><td><?= (int)$game['estoque'] ?></td><td><div class="row-actions"><a class="icon-btn" href="index.php?entidade=games&acao=editar&id=<?= (int)$game['id'] ?>" title="Editar">✏️</a><form method="post" action="index.php?entidade=games&acao=excluir" class="inline-form" onsubmit="return confirm('Excluir este jogo?')"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><input type="hidden" name="id" value="<?= (int)$game['id'] ?>"><button class="icon-btn danger" type="submit" title="Excluir">🗑️</button></form></div></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?></section>
